const LOCALE_INDEX={en:1,vi:2,'zh-CN':3,ru:4,km:5};
const COPY_MAP=new Map(COPY.map(row=>[row[0],row]));
const WEEKDAYS={ko:['일','월','화','수','목','금','토'],en:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],vi:['CN','T2','T3','T4','T5','T6','T7'],'zh-CN':['周日','周一','周二','周三','周四','周五','周六'],ru:['Вс','Пн','Вт','Ср','Чт','Пт','Сб'],km:['អាទិត្យ','ចន្ទ','អង្គារ','ពុធ','ព្រហស្បតិ៍','សុក្រ','សៅរ៍']};
const AREAS={'송정1동':'Songjeong 1-dong','송정2동':'Songjeong 2-dong','도산동':'Dosan-dong','우산동':'Usan-dong','월곡1동':'Wolgok 1-dong','월곡2동':'Wolgok 2-dong','비아동':'Bia-dong','하남동':'Hanam-dong','첨단1동':'Cheomdan 1-dong','첨단2동':'Cheomdan 2-dong','신흥동':'Sinheung-dong','어룡동':'Eoryong-dong','신가동':'Singa-dong','운남동':'Unnam-dong','신창동':'Sinchang-dong','수완동':'Suwan-dong','평동':'Pyeong-dong','삼도동':'Samdo-dong','본량동':'Bollyang-dong','동곡동':'Donggok-dong','임곡동':'Imgok-dong','평동산단1단지':'Pyeongdong Industrial Area 1','평동산단2단지':'Pyeongdong Industrial Area 2','평동산단3단지':'Pyeongdong Industrial Area 3','빛그린산단':'Bitgreen Industrial Area','진곡산단':'Jingok Industrial Area','하남산단':'Hanam Industrial Area'};
const PATTERNS=COPY.filter(row=>row[0].includes('{')).map(row=>{
  const names=[];const pattern=row[0].split(/(\{\w+\})/).map(part=>{if(part.startsWith('{')){names.push(part.slice(1,-1));return '(.*?)'}return part.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}).join('');
  return {regex:new RegExp('^'+pattern+'$'),names,row};
});
let locale='ko';
try{const candidate=new URLSearchParams(location.search).get('lang')||localStorage.getItem('gwangsan-language');if(LANGUAGE_OPTIONS.some(option=>option.code===candidate))locale=candidate}catch{}
function format(row,variables={}){return row[locale==='ko'?0:LOCALE_INDEX[locale]].replace(/\{(\w+)\}/g,(_,key)=>key==='value'?String(variables[key]??'').split(' · ').map(translate).join(' · '):translate(variables[key]??''))}
function translate(value){
  const source=String(value??'');if(locale==='ko')return source;
  const text=source.trim(),padding=source.match(/^(\s*)[\s\S]*?(\s*)$/);
  let result=text;
  const direct=COPY_MAP.get(text);
  if(direct)result=direct[LOCALE_INDEX[locale]];
  else if(/^\d+월 \d+일$/.test(text)){const [month,day]=text.match(/\d+/g).map(Number);result=locale==='km'?day+'/'+month:new Intl.DateTimeFormat(locale,{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(2026,month-1,day)))}
  else if(/^\(\d+월 \d+일\)$/.test(text))result='('+translate(text.slice(1,-1))+')';
  else if(/^.+ \(\d+월 \d+일\)$/.test(text)){const match=text.match(/^(.+) \((\d+월 \d+일)\)$/);result=translate(match[1])+' ('+translate(match[2])+')'}
  else if(text.startsWith('·')&&text.slice(1).includes(' · '))result=text.slice(1).trim().split(' · ').map(part=>translate('· '+part)).join(' ');
  else if(/^[일월화수목금토]$/.test(text))result=WEEKDAYS[locale][WEEKDAYS.ko.indexOf(text)];
  else if(/^[일월화수목금토](?:[·~][일월화수목금토])*요일$/.test(text))result=text.replace('요일','').split(/([·~])/).map(part=>part==='~'?'–':WEEKDAYS.ko.includes(part)?WEEKDAYS[locale][WEEKDAYS.ko.indexOf(part)]:part).join('');
  else{
    for(const entry of PATTERNS){const match=entry.regex.exec(text);if(match){result=format(entry.row,Object.fromEntries(entry.names.map((name,i)=>[name,match[i+1]])));break}}
  }
  return (padding?.[1]||'')+result+(padding?.[2]||'');
}
const originals=new WeakMap();
function localizeRecord(node,key,value,set){
  let records=originals.get(node);if(!records){records={};originals.set(node,records)}
  let record=records[key];if(!record||record.rendered!==value)record=records[key]={source:value,rendered:value};
  let rendered=translate(record.source);
  if(node.nodeType===Node.TEXT_NODE&&node.parentElement?.tagName==='OPTION'&&locale!=='ko'&&AREAS[record.source])rendered=record.source+' · '+AREAS[record.source];
  if(rendered!==value)set(rendered);record.rendered=rendered;
}
function applyTranslations(root=document.body){
  if(!root)return;
  function visit(node){
    if(node.nodeType===Node.TEXT_NODE){if(!node.parentElement?.closest('script,style,textarea,[translate="no"]'))localizeRecord(node,'text',node.nodeValue,v=>node.nodeValue=v);return}
    if(node.nodeType!==Node.ELEMENT_NODE||node.matches('script,style,[translate="no"]'))return;
    for(const key of ['placeholder','aria-label','title','alt','label'])if(node.hasAttribute(key))localizeRecord(node,key,node.getAttribute(key),v=>node.setAttribute(key,v));
    for(const child of node.childNodes)visit(child);
  }
  visit(root);
}
function setLocale(value){
  if(!LANGUAGE_OPTIONS.some(option=>option.code===value))return;
  locale=value;document.documentElement.lang=locale;
  try{localStorage.setItem('gwangsan-language',locale)}catch{}
  document.getElementById('language-current').textContent=LANGUAGE_OPTIONS.find(option=>option.code===locale).name;
  document.querySelectorAll('[data-language]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.language===locale)));
  document.title=translate('광산 버릴지도');applyTranslations();
  dispatchEvent(new CustomEvent('app:languagechange',{detail:locale}));
}
const DEFAULT_QUESTIONS=['분리되지 않는 부분은 어떻게 버리나요?','오염이 남아 있으면 어떻게 하나요?','버릴 때 특히 주의할 점은 무엇인가요?','재질 표시가 없으면 무엇을 확인하나요?','봉투에 들어가지 않는 크기라면 어떻게 하나요?','깨진 부분은 어떻게 포장하나요?','배출 방법을 짧게 정리해 주세요.','정확한 지역 기준은 어디에 문의하나요?'];
window.I18n={get locale(){return locale},t:translate,setLocale,apply:applyTranslations,languages:LANGUAGE_OPTIONS,defaultQuestions:()=>DEFAULT_QUESTIONS.map(translate)};
const dialog=document.getElementById('language-dialog');
document.getElementById('language-options').innerHTML=LANGUAGE_OPTIONS.map(option=>'<button type="button" data-language="'+option.code+'" translate="no"><span>'+option.tag+'</span><span class="language-option-name"><strong lang="ko">'+option.korean+'</strong>'+(option.code==='ko'?'':'<small lang="'+option.code+'">'+option.name+'</small>')+'</span><b aria-hidden="true">✓</b></button>').join('');
document.getElementById('language-open').addEventListener('click',()=>{dialog.showModal();dialog.querySelector('[aria-pressed="true"]')?.focus()});
document.getElementById('language-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{const button=event.target.closest('[data-language]');if(button){setLocale(button.dataset.language);dialog.close()}else if(event.target===dialog&&event.offsetX<0)dialog.close()});
setLocale(locale);
new MutationObserver(records=>{
  const roots=new Set();for(const record of records){if(record.type==='childList'){for(const node of record.addedNodes)roots.add(node)}else roots.add(record.target)}
  for(const root of roots){if(root.isConnected){if(root.nodeType===Node.TEXT_NODE)applyTranslations(root.parentElement);else applyTranslations(root)}}
}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title','alt','label']});
